import{_ as a,o as s,c as n}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"Page 2 - linux | Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"linux/page/2","tag":"linux","title":"Page 2 - linux | Tag","prev":"/tags/linux/","next":"/tags/linux/page/3/","posts":[{"title":"Linux下恢复误删除的文件","url":"/posts/2014-07-21-linux-undelete-files/","date":"2014-07-21 17:39","tags":["linux"],"html":"<p>经常有时候喜欢删除文件...但是之后又后悔删除... Linux 下 rm 之后是没有回收站的.<br>\\n于是我便寻找恢复文件的相关资料.</p>\\n<h2 id=\\"testdisk\\" tabindex=\\"-1\\">TestDisk <a class=\\"header-anchor\\" href=\\"#testdisk\\" aria-label=\\"Permalink to &quot;TestDisk&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>TestDisk 是用来帮助恢复丢失的分区和使无法启动的启动盘再次启动.<br>\\n使用 TestDisk 之前别忘了备份分区表.</p>\\n<h3 id=\\"备份分区表\\" tabindex=\\"-1\\">备份分区表 <a class=\\"header-anchor\\" href=\\"#备份分区表\\" aria-label=\\"Permalink to &quot;备份分区表&quot;\\">&ZeroWidthSpace;</a></h3>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># sfdisk -d /dev/sda > /tmp/sda.bak</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h3 id=\\"恢复分区表\\" tabindex=\\"-1\\">恢复分区表 <a class=\\"header-anchor\\" href=\\"#恢复分区表\\" aria-label=\\"Permalink to &quot;恢复分区表&quot;\\">&ZeroWidthSpace;</a></h3>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># sfdisk /dev/sda &#x3C; /tmp/sda.bak</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>官方教程:<a href=\\"http://www.cgsecurity.org/wiki/TestDisk_Step_By_Step\\" target=\\"_blank\\" rel=\\"noreferrer\\">TestDisk Step By Step</a></p>\\n<h2 id=\\"photorec\\" tabindex=\\"-1\\">PhotoRec <a class=\\"header-anchor\\" href=\\"#photorec\\" aria-label=\\"Permalink to &quot;PhotoRec&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>PhotoRec 是用来恢复丢失的文件和照片.即使重新格式化或严重损坏的文件系统都可以恢复.\\n但是 PhotoRec 只有全盘扫描和空闲分区扫描.耗时很长.对于自己无意中删除的小文件来说就是\\n杀鸡焉用牛刀.没有这个必要.</p>\\n<h2 id=\\"extundelete\\" tabindex=\\"-1\\">Extundelete <a class=\\"header-anchor\\" href=\\"#extundelete\\" aria-label=\\"Permalink to &quot;Extundelete&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Extundelete 设计的就是用来从 ext3 或 ext4 的分区恢复最近被删除的文件.它可以从一个相对路径恢复\\n被删除的文件,非常实用.但是只有当分区被卸载才可以使用.</p>\\n<h3 id=\\"恢复被删除的文件\\" tabindex=\\"-1\\">恢复被删除的文件 <a class=\\"header-anchor\\" href=\\"#恢复被删除的文件\\" aria-label=\\"Permalink to &quot;恢复被删除的文件&quot;\\">&ZeroWidthSpace;</a></h3>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># extundelete --restore-file tux/cv.tex /dev/sda4</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h3 id=\\"恢复被删除的文件目录\\" tabindex=\\"-1\\">恢复被删除的文件目录 <a class=\\"header-anchor\\" href=\\"#恢复被删除的文件目录\\" aria-label=\\"Permalink to &quot;恢复被删除的文件目录&quot;\\">&ZeroWidthSpace;</a></h3>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># extundelete --restore-directory tux/Documents/tex/ /dev/sda4</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>Arch wiki:<a href=\\"https://wiki.archlinux.org/index.php/File_recovery\\" target=\\"_blank\\" rel=\\"noreferrer\\">File recovery</a></p>\\n"},{"title":"Archlinux下声卡的设置与折腾","url":"/posts/2014-06-05-archlinux-sound-setting/","date":"2014-06-05 09:22","tags":["linux"],"html":"<p>最近又有瞎折腾装 Arch....发现显卡驱动的安装和设置都不是问题...\\n声卡却老是出现奇怪的问题,便把最近折腾的经验写下来吧~</p>\\n<h2 id=\\"切换默认声卡\\" tabindex=\\"-1\\">切换默认声卡 <a class=\\"header-anchor\\" href=\\"#切换默认声卡\\" aria-label=\\"Permalink to &quot;切换默认声卡&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>发现最近的新本子基本上声卡设备都不止一个,个人猜测应该是 HDMI 音频输出和\\n本机主板上的音频输出吧.可以使用 <code>aplay -l</code> 命令显示所有声卡设备.\\n我机器的输出是:</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">[acgotaku@Archlinux </span><span style=\\"color:#D73A49\\">~</span><span style=\\"color:#24292E\\">]$ aplay -l</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">****</span><span style=\\"color:#24292E\\"> List of PLAYBACK Hardware Devices </span><span style=\\"color:#D73A49\\">****</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">card</span><span style=\\"color:#032F62\\"> 0:</span><span style=\\"color:#032F62\\"> HDMI</span><span style=\\"color:#24292E\\"> [HDA </span><span style=\\"color:#032F62\\">Intel</span><span style=\\"color:#032F62\\"> HDMI],</span><span style=\\"color:#032F62\\"> device</span><span style=\\"color:#032F62\\"> 3:</span><span style=\\"color:#032F62\\"> HDMI</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\"> [HDMI </span><span style=\\"color:#032F62\\">0]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevices:</span><span style=\\"color:#032F62\\"> 1/1</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevice</span><span style=\\"color:#6A737D\\"> #0: subdevice #0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">card</span><span style=\\"color:#032F62\\"> 1:</span><span style=\\"color:#032F62\\"> PCH</span><span style=\\"color:#24292E\\"> [HDA </span><span style=\\"color:#032F62\\">Intel</span><span style=\\"color:#032F62\\"> PCH],</span><span style=\\"color:#032F62\\"> device</span><span style=\\"color:#032F62\\"> 0:</span><span style=\\"color:#032F62\\"> ALC3220</span><span style=\\"color:#032F62\\"> Analog</span><span style=\\"color:#24292E\\"> [ALC3220 </span><span style=\\"color:#032F62\\">Analog]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevices:</span><span style=\\"color:#032F62\\"> 1/1</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  Subdevice</span><span style=\\"color:#6A737D\\"> #0: subdevice #0</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>第一个一般为默认的声卡输出设备,显然 HDMI 输出是不对的,导致声音无法正常播放,我们应该把默认声卡切换为\\n第二个.最简单易用的方法是在用户根目录下新建一个 .asoundrc 文件.输入以下内容:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>defaults.pcm.card 1</span></span>\\n<span class=\\"line\\"><span>defaults.pcm.device 0</span></span>\\n<span class=\\"line\\"><span>defaults.ctl.card 1</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>上面的数据可以从声卡设备输出中找到,这样就切换到 card 1 的 device 0 设备了.不过切换之后可能发现还是没有\\n声音,因为 alsa 默认是静音的需要手动解除才行. 这就需要去官方源安装 <code>alsamixer</code> 工具. <a href=\\"https://www.archlinux.org/packages/?name=alsa-utils\\" target=\\"_blank\\" rel=\\"noreferrer\\">alsa-utils</a>\\n我自己安装的 alsamixer 使用界面是:</p>\\n<p><img src=\\"/assets/alsamixer.png\\" alt=\\"alsamixer\\"></p>\\n<p>默认 Master 竖条下方显示的不是 00 而是 MM,表示是静音的,按下 m 键解除静音.</p>\\n<h2 id=\\"耳机有持续的杂音的解决方案\\" tabindex=\\"-1\\">耳机有持续的杂音的解决方案 <a class=\\"header-anchor\\" href=\\"#耳机有持续的杂音的解决方案\\" aria-label=\\"Permalink to &quot;耳机有持续的杂音的解决方案&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有些情况下即使安装好 alsa 解除静音了,但仍然发现戴耳机的时候没有任何软件发声的时候会有持续的杂音,但是音乐播放器一旦放音乐的时候杂音又消失了.\\n这个问题的原因是 alsa 默认设置 Mic 声道是静音的,我们只需要解除 Mic 声道的静音并调节至合适的值即可.</p>\\n<h2 id=\\"恢复默认的-alsa-设置\\" tabindex=\\"-1\\">恢复默认的 alsa 设置 <a class=\\"header-anchor\\" href=\\"#恢复默认的-alsa-设置\\" aria-label=\\"Permalink to &quot;恢复默认的 alsa 设置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有些时候自己胡乱设置导致 alsa 无法正常工作的时候可以通过使用 <code>alsactl restore</code> 命令使 alsa 恢复到默认的配置一般都能正常工作了.</p>\\n"},{"title":"Archlinux折腾笔记","url":"/posts/2014-04-20-linux-notes/","date":"2014-04-20 19:52","tags":["notes","linux"],"html":"<p>四月也算过去了一大半了,经过了一个月的奔波与折腾,总算安顿好自己了.在学校本地找了一个还算不错的实习.\\n阴差阳错的选择了 Web 开发工程师的职位,其实我最想做的是后端开发,前端也还是比较喜欢的.但是我有个很大的\\n缺点就是不会设计... 不会设计的前端开发工程师很鸡肋的,每次网站开发都是同学出设计图我来做的.这样不行的,\\n我必须能独当一面才算能在公司站得住脚.</p>\\n<p>近况就是这些,接下来就是记录下自己在 Archlinux 下折腾的东西.方便自己以后查询使用.</p>\\n<h2 id=\\"linux-下视频截图制作动态-gif\\" tabindex=\\"-1\\">Linux 下视频截图制作动态 GIF <a class=\\"header-anchor\\" href=\\"#linux-下视频截图制作动态-gif\\" aria-label=\\"Permalink to &quot;Linux 下视频截图制作动态 GIF&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>观看视频遇到经典的镜头当然得录下来做成 GIF~\\n首先需要安装 <code>imagemagick</code> 这个软件包才行</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">mplayer</span><span style=\\"color:#005CC5\\"> -vo</span><span style=\\"color:#032F62\\"> png</span><span style=\\"color:#005CC5\\"> -ss</span><span style=\\"color:#032F62\\"> 00:08:28</span><span style=\\"color:#005CC5\\"> -frames</span><span style=\\"color:#005CC5\\"> 200</span><span style=\\"color:#032F62\\"> 123.mp4</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">mogrify</span><span style=\\"color:#005CC5\\"> -resize</span><span style=\\"color:#032F62\\"> 848x480</span><span style=\\"color:#005CC5\\"> *</span><span style=\\"color:#032F62\\">.png</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">convert</span><span style=\\"color:#005CC5\\"> -delay</span><span style=\\"color:#005CC5\\"> 4</span><span style=\\"color:#005CC5\\">  *</span><span style=\\"color:#032F62\\">.png</span><span style=\\"color:#032F62\\"> ry.gif</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>第一句话是利用 mplayer 输出 png 格式图片,从 8 分 28 秒开始,截图 200 帧,也可以换成</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">mplayer</span><span style=\\"color:#005CC5\\"> -vo</span><span style=\\"color:#032F62\\"> png:z=</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#005CC5\\"> -ss</span><span style=\\"color:#032F62\\"> 00:08:28</span><span style=\\"color:#005CC5\\"> -endpos</span><span style=\\"color:#005CC5\\"> 8</span><span style=\\"color:#032F62\\">  123.mp4</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样就是截取 8 秒,png 后面的 z=1 是压缩比例从 0 到 9 压缩程度递增,压缩速度也递增.\\n第二行便是修改尺寸,毕竟 720p 的 GIF 实在是吃不消啊.然后第三行变把这些 png 生成 GIF 了.</p>\\n<h2 id=\\"sudo-设置环境变量\\" tabindex=\\"-1\\">sudo 设置环境变量 <a class=\\"header-anchor\\" href=\\"#sudo-设置环境变量\\" aria-label=\\"Permalink to &quot;sudo 设置环境变量&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有时候程序需要使用 root 权限,但当我使用 sudo 的时候结果发现这时候程序又使用 root 用户的配置文件了.<br>\\n现在的需求就是程序使用 root 权限运行但是执行时候读取 HOME 变量还是当前用户.<br>\\n<a href=\\"https://wiki.archlinux.org/index.php/Sudo#Run_X11_apps_using_sudo\\" target=\\"_blank\\" rel=\\"noreferrer\\">Run_X11_apps_using_sudo</a>\\nwiki 上有清楚的讲解这样的解决办法.</p>\\n"}]},"relativePath":"tags/linux/page/2/index.md","filePath":"tags/[slug].md"}'),e={name:"tags/linux/page/2/index.md"};function l(p,r,o,t,i,c){return s(),n("div")}const h=a(e,[["render",l]]);export{u as __pageData,h as default};
